import json


def run(text: str) -> str:
    quantities = {}
    total = 0
    invalid = 0

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            continue

        separator = next((i for i, char in enumerate(line) if char in ':：'), -1)
        if separator < 0:
            invalid += 1
            continue

        name = line[:separator].strip()
        digits = line[separator + 1:].strip()
        if not name or not digits or not all('0' <= char <= '9' for char in digits):
            invalid += 1
            continue

        quantity = int(digits)
        quantities[name] = quantities.get(name, 0) + quantity
        total += quantity

    result = {
        'items': [{'name': name, 'quantity': quantity} for name, quantity in quantities.items()],
        'total': total,
        'invalid': invalid,
    }
    return json.dumps(result, ensure_ascii=False, separators=(',', ':'))
